// Per-building data. Where each building stands lives in the map
// (public/world/map/island.json, object layer "zones", one point per id at the
// building's base-centre - generated by scripts/world/build-map.mjs, and
// editable in Tiled). This holds what the map can't express. WorldScene
// measures the drawn art at runtime and derives the collision box, trigger,
// label and tap area from it plus:
//   frame     atlas frame drawn bottom-anchored at the map point
//   depth     how far back from the base the building is solid, in px - the
//             rest of the art is roof the player can walk behind
//   solidW    collision width when it should be narrower than the art (the
//             sign's post); otherwise the art width minus a small inset
//   doorDx    x offset of the door from the map point - the trigger, the tap
//             walk-to point and the E prompt all sit in front of it
export const ZONES = [
  { id: 'spawn', title: 'Welcome', frame: 'signpost', depth: 6, solidW: 8, doorDx: 0 },
  { id: 'workshop', title: 'Workshop', frame: 'workshop', depth: 34, doorDx: -5 },
  { id: 'tower', title: 'Tower', frame: 'tower', depth: 28, doorDx: -2 },
  { id: 'shrine', title: 'Shrine', frame: 'shrine', depth: 30, doorDx: -4 },
  { id: 'garden', title: 'Garden', frame: 'shed', depth: 28, doorDx: -7 },
  { id: 'terminal', title: 'Terminal', frame: 'terminal_desk', depth: 14, doorDx: 0 },
  { id: 'archive', title: 'Archive', frame: 'archive', depth: 30, doorDx: 0 },
]
